#!/usr/bin/env node
"use strict";
// Explicit OFFLINE operator interface. No RPC calls, witness signers or keys
// are generated by this CLI; pins must come from an out-of-band trusted file.
const fs=require("node:fs"),path=require("node:path");
const Database=require("better-sqlite3");
const {validatePins}=require("./blockchain-finality-witness-verifier.cjs");
const {openWitnessState,issue,accept,quorum}=require("./blockchain-finality-witness-store.cjs");
function parse(argv){
  const options={command:null,db:null,state:null,pins:null,signature:null,
    kind:null,address:null,keyId:null,file:null};
  const allowed=new Set(["--db","--state","--pins","--signature","--kind",
    "--address","--key-id","--file"]);
  if(!["issue","accept","quorum"].includes(argv[0]))throw Error(
    "Usage: issue|accept|quorum --db existing.db --state separate.db --pins trusted.json [--signature SIG --kind wallet --address PUBKEY --key-id WITNESS] [--file signed-receipt.json]");
  options.command=argv[0];
  const seen=new Set();
  for(let i=1;i<argv.length;i++){
    const f=argv[i];
    if(!allowed.has(f)||seen.has(f)||!argv[i+1]||argv[i+1].startsWith("--"))
      throw Error("Unsupported, duplicated or missing witness CLI argument");
    seen.add(f);
    const key=f==="--key-id"?"keyId":f.slice(2);
    options[key]=argv[++i];
  }
  if(!options.db||!options.state||!options.pins)throw Error("Explicit db, state and pins required");
  if(options.command==="issue"&&(!options.kind||!options.address||!options.signature||!options.keyId||options.file))
    throw Error("Issue requires kind, address, signature and key-id, not file");
  if(options.command==="accept"&&(!options.file||options.kind||options.address||options.signature||options.keyId))
    throw Error("Accept requires only --file plus db/state/pins");
  if(options.command==="quorum"&&(!options.kind||!options.address||!options.signature||options.keyId||options.file))
    throw Error("Quorum requires kind/address/signature, not key-id/file");
  return options;
}
function readJson(p,max){
  if(typeof p!=="string"||!path.isAbsolute(p))throw Error("Explicit absolute JSON file required");
  const stat=fs.statSync(p);
  if(!stat.isFile()||stat.size>max||stat.size<2)throw Error("JSON file size invalid");
  return JSON.parse(fs.readFileSync(p,"utf8"));
}
function main(argv=process.argv.slice(2),{clock=Date.now}={}){
  const o=parse(argv);
  const config=readJson(o.pins,16*1024);
  if(!config||Object.keys(config).sort().join(",")!=="recoveryEpoch,witnesses")
    throw Error("Trust config requires only recoveryEpoch and witnesses");
  // Store APIs validate the serialized trust config themselves. Compiled pins
  // include a KeyObject and are deliberately not accepted as config entries.
  validatePins(config.witnesses);
  const pins=config.witnesses;
  for(const v of [o.db,o.state]){
    if(!path.isAbsolute(v))throw Error("Absolute db/state paths required");
  }
  if(!fs.existsSync(o.db))throw Error("Source SQLite absent");
  if(o.command!=="issue"&&!fs.existsSync(o.state))
    throw Error("Witness state has not been initialized by challenge issue");
  const source=new Database(o.db,{readonly:true,fileMustExist:true});
  let state;
  try{
    source.pragma("query_only=ON");
    state=openWitnessState(o.state,{sourcePath:o.db,recoveryEpoch:config.recoveryEpoch});
    let result;
    if(o.command==="issue")result=issue(source,state,{
      pins,keyId:o.keyId,signature:o.signature,kind:o.kind,address:o.address,clock});
    else if(o.command==="accept")result=accept(source,state,{
      pins,envelope:readJson(o.file,64*1024),clock});
    else result=quorum(source,state,{
      pins,signature:o.signature,kind:o.kind,address:o.address});
    return result;
  }finally{state?.close();source.close();}
}
if(require.main===module){
  try{console.log(JSON.stringify(main(),null,2));}
  catch(e){console.error(e.message);process.exitCode=1;}
}
module.exports={parse,readJson,main};
